import{_ as r,l as i,o as a,c as A,v as e,p as n,x as t,d as s,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"all-to-all 实现","description":"","frontmatter":{"title":"all-to-all 实现","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/all-to-all-impl.md","filePath":"llm/all-to-all-impl.md","lastUpdated":1789023840000}'),d={name:"llm/all-to-all-impl.md"};function m(c,l,h,N,_,u){const o=i("Mermaid");return a(),A("div",null,[l[1]||(l[1]=e('<h1 id="all-to-all-实现" tabindex="-1">all-to-all 实现 <a class="header-anchor" href="#all-to-all-实现" aria-label="Permalink to &quot;all-to-all 实现&quot;">​</a></h1><div class="epigraph"><p>归约可以在中途把多份合成一份；置换必须让每对端点的字节真的到达对端。All-to-All 的体积因此按「每卡发给其余每卡」计，层次化帮不上加法。</p><footer>—— 对照 MPI Alltoall 与专家并行里的 token 置换；拓扑对照见机内全互连 vs Clos</footer></div><p><a href="/llm/reduce-scatter-allgather">上一课</a> 的一对原语都还带「可加」或「只拼接已切好的片」。本课换成 <strong>置换</strong>：每张卡有 \\(N\\) 块，第 \\(j\\) 块要送到卡 \\(j\\)。专家并行把 token 按路由结果重排，走的就是这条原语；序列并行的某些切分也会用。缺口是实现： pairwise 交换、Bruck 一类指数调度、以及为何跨节点 EP 会把 <a href="/llm/pretrain-comm">预训练通信</a> 里闲置的 NVLink 变成旁观者。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记每卡发给每个对端 \\(m\\) 字节（对角给自己，通常只本地拷贝）。完全交换的总量是每卡 \\((N-1)m\\)，集群合计 \\(\\Theta(N^2 m)\\)。MoE 里 \\(m\\) 随本步被路由到该专家的 token 数而变，负载不均时热专家所在节点既是计算热点也是网络热点。All-Reduce 可以先加后传，跨节点只走每节点一份；All-to-All 没有可加中间结果，节点内 <a href="/llm/nvlink">NVLink</a> 再快，也替不了「发给另一柜那张 GPU」的那一段。</p><p>实现还要在两种坏里选：一次把 \\(N-1\\) 个对端的消息同时打出去，网卡队列爆炸；或打成 \\(N-1\\) 轮两两交换，延迟线性涨。小 \\(N\\)、大 \\(m\\) 与大 \\(N\\)、小 \\(m\\) 的最优调度不同。问题是：<strong>调度如何让链路满而不让交换机缓冲区先满</strong>。</p><p><span class="marginnote">NCCL 的 Alltoall 对训练暴露为一条集体调用；底层可能拆成并行的 Send/Recv。框架若自己用点对点拼 All-to-All 而不注册通信组，会丢掉拓扑感知与 chunk 流水，MoE 一步的尾延迟立刻可见。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>pairwise 交换：第 \\(k\\) 步，卡 \\(i\\) 与 \\(i\\oplus k\\) 交换（或环上与 \\(i+k\\)）。\\(N-1\\) 步覆盖所有对；每步每卡只处理一个对端，注入带宽可控。适合大消息、小进程组。</p><p>Bruck / 指数调度：每步把已持有的块倍增式转发出去，步数 \\(O(\\log N)\\)，适合小消息、大 \\(N\\)。代价是中间缓冲区更大，实现更绕。NCCL 按消息大小与拓扑在这些族里选，与 All-Reduce 的环/树切换是同一思想，对象换成置换。</p><p>层次化只能做「先节点内重排，再跨节点交换节点级块，再节点内分发」。它减少的是<strong>小消息条数</strong>（把许多 GPU 对聚合成节点对），不减少跨节点净荷——token 该去别的节点，字节仍要过网卡。EP 组尽量缩在 NVLink 域内，是因为域内置换走 Switch，域外置换走 Clos，屋顶线差一档，见 <a href="/llm/all-to-all-vs-clos">全互连 vs Clos</a>。</p>',11)),(a(),n(E,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22%E5%90%84%E5%8D%A1%20token%22%5D%20--%3E%20RT%5B%22%E8%B7%AF%E7%94%B1%E5%86%B3%E5%AE%9A%E7%9B%AE%E6%A0%87%E4%B8%93%E5%AE%B6%22%5D%0A%20%20RT%20--%3E%20A2A%5B%22All-to-All%20%E7%BD%AE%E6%8D%A2%22%5D%0A%20%20A2A%20--%3E%20EX%5B%22%E7%9B%AE%E6%A0%87%E5%8D%A1%E4%B8%8A%E7%9A%84%E4%B8%93%E5%AE%B6%E8%AE%A1%E7%AE%97%22%5D%0A%20%20EX%20--%3E%20A2AB%5B%22All-to-All%20%E6%8D%A2%E5%9B%9E%22%5D%0A%20%20A2A%20--%3E%20INTRA%5B%22%E5%9F%9F%E5%86%85%3A%20NVLink%20Switch%22%5D%0A%20%20A2A%20--%3E%20INTER%5B%22%E8%B7%A8%E5%9F%9F%3A%20%E7%BD%91%E5%8D%A1%20%2F%20Clos%22%5D%0A"})]),fallback:t(()=>[...l[0]||(l[0]=[s(" Loading... ",-1)])]),_:1})),l[2]||(l[2]=e('<p>负载不均时，集体语义仍是「所有 rank 等到最慢那对」。热专家的 \\(m\\) 变大，整步被它绑住。容量因子、drop、或对专家再切并行，是模型侧减压；网络侧只能保证调度别雪上加霜。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>All-to-All 的 \\(\\alpha\\)–\\(\\beta\\) 模型与 All-Reduce 不同：没有 \\(\\frac{N-1}{N}\\) 那种「加完变少」的系数，数据项往往是 \\((N-1)m\\beta\\) 量级，再乘算法效率。小 \\(m\\) 时 \\(N\\) 个对端各付一次 \\(\\alpha\\)，延迟区比同等体积的 All-Reduce 更惨——这是 MoE 微批太小时 EP 墙的来源之一。</p><p>拓扑上，rail-optimized 脂肪树希望「同号 GPU 走同一轨」。All-to-All 却几乎是均匀随机对，轨对齐帮不上「任意到任意」，反而可能把流量打进同一叶子的上行。后课 rail 与拥塞会回到这一点：集合算法选对了，流量模式仍可能与拓扑的设计假设冲突。</p><p><span class="marginnote">Decode 推理的 EP All-to-All 更苛刻：batch 小，\\(m\\) 更小，更容易掉进延迟区。训练微批掩盖的问题，服务上会变成尾巴。不要用训练的 EP 度直接当推理拓扑。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 All-to-All 画成「就是 N 次 All-Gather」。语义不同，优化不同。不要假设 NVLink SHARP 一类网内计算能加速置换——归约才能卸载加法，置换没有加法。不要在以太网 Clos 上用 128 路 EP 去模拟 NVLink 域内宽专家；测的是 hop 与拥塞，不是算力。</p><p>实现若允许变长（每对 \\(m_{ij}\\) 不同），还要先交换元数据。路由极度倾斜时，元数据本身不是墙，净荷倾斜才是。对不齐的切分（专家数不能整除 EP 度）制造空洞消息，仍占一轮 \\(\\alpha\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>All-to-All 是置换，跨节点体积不能靠先加后传来减。</li><li>大消息用 pairwise 交换，小消息用对数步调度；NCCL 按 size 选。</li><li>层次化减的是消息条数，不是 MoE 跨柜净荷。</li><li>EP 组应优先落在 NVLink 域；跨域 All-to-All 是训练与推理的常见墙。</li><li>出处：MPI Alltoall 调度族；NCCL；MoE 系统对 EP 通信的实践。</li></ul>',10))])}const P=r(d,[["render",m]]);export{B as __pageData,P as default};
